SELECT
w.*
FROM
wms_material_inventory w
LEFT JOIN (
SELECT
m.material_inventory_id,
SUM(m.total_quantity) AS total_frozen_quantity
FROM
wms_material_freeze m
where m.bool_delete_enum = 0
GROUP BY
m.material_inventory_id
) mf ON w.id = mf.material_inventory_id
WHERE
w.use_status = 0
AND w.bool_virtual = 0
AND w.bool_delete_enum = 0

    and w.id in
    
        #{item}
    


    and w.basic_class = #{basicClass}


    and w.thickness >= #{minThickness}


    and w.thickness <= #{thickness}


    
        and w.specification = #{specification}
    


    and classify_id in
    
        #{item}
    


    and w.project_id = #{projectId}


    and w.warehouse_id = #{warehouseId}


    and w.bool_party_a = #{boolPartyA}


    and w.material_is_whole = #{materialIsWhole}


    and w.warehouse_type = #{projectWarehouseType}


    and w.workshop_id in
    
        #{item}
    

AND COALESCE(mf.total_frozen_quantity, 0) != COALESCE((SELECT wmi.quantity FROM wms_material_inventory wmi WHERE
wmi.id = w.id), 0)

